                 //             "size":0,
                 //             "state":"cancelled",
                 //             "stop_order_type":null,
                 //             "stop_price":null,
                 //             "stop_trigger_method":"mark_price",
                 //             "time_in_force":"gtc",
                 //             "trail_amount":null,
                 //             "unfilled_size":0,
                 //             "user_id":22142
                 //         },
                 //         "success":true
