    //         "open": 946.0,
    //         "price_band": {
    //             "lower_limit": "133.37794509",
    //             "upper_limit": "5663.66930164"
    //         },
    //         "product_id": 116171,
    //         "quotes": {
    //             "ask_iv": "0.36932389",
    //             "ask_size": "1321",
    //             "best_ask": "1054",
    //             "best_bid": "1020",
    //             "bid_iv": "0.34851914",
    //             "bid_size": "2202",
    //             "impact_mid_price": null,
    //             "mark_iv": "0.35896335"
    //         },
    //         "size": 152,
    //         "spot_price": "30178.53195697",
    //         "strike_price": "29500",
    //         "symbol": "C-BTC-29500-280723",
    //         "timestamp": 1689834695286094,
    //         "turnover": 4546.601744940001,
    //         "turnover_symbol": "USDT",
    //         "turnover_usd": 4546.601744940001,
    //         "volume": 0.15200000000000002
    //     }
    //
    ccxt::any timestamp =
        this->safeIntegerProduct(interest, std::string("timestamp"), 0.001);
    ccxt::any marketId = this->safeString(interest, std::string("symbol"));
    return this->safeOpenInterest(
        ccxt::dict{
            {std::string("symbol"), this->safeSymbol(marketId, market)},
            {std::string("baseVolume"),
             this->safeNumber(interest, std::string("oi_value"))},
            {std::string("quoteVolume"),
             this->safeNumber(interest, std::string("oi_value_usd"))},
            {std::string("openInterestAmount"),
             this->safeNumber(interest, std::string("oi_contracts"))},
            {std::string("openInterestValue"),
             this->safeNumber(interest, std::string("oi"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("info"), interest},
        },
        market);
