  ccxt::any parseGreeks(ccxt::any greeks,
                        ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "close": 6793.0,
    //         "contract_type": "call_options",
    //         "greeks": {
    //             "delta": "0.94739174",
    //             "gamma": "0.00002206",
    //             "rho": "11.00890725",
    //             "spot": "36839.58124652",
    //             "theta": "-18.18365310",
    //             "vega": "7.85209698"
    //         },
    //         "high": 7556.0,
    //         "low": 6793.0,
    //         "mark_price": "6955.70698909",
    //         "mark_vol": "0.66916863",
    //         "oi": "1.8980",
    //         "oi_change_usd_6h": "110.4600",
    //         "oi_contracts": "1898",
    //         "oi_value": "1.8980",
    //         "oi_value_symbol": "BTC",
    //         "oi_value_usd": "69940.7319",
    //         "open": 7.2e3,
    //         "price_band": {
    //             "lower_limit": "5533.89814767",
    //             "upper_limit": "11691.37688371"
    //         },
    //         "product_id": 129508,
    //         "quotes": {
    //             "ask_iv": "0.90180438",
    //             "ask_size": "1898",
    //             "best_ask": "7210",
    //             "best_bid": "6913",
    //             "bid_iv": "0.60881706",
    //             "bid_size": "3163",
    //             "impact_mid_price": null,
    //             "mark_iv": "0.66973549"
    //         },
    //         "size": 5,
    //         "spot_price": "36839.58153868",
    //         "strike_price": "30000",
    //         "symbol": "C-BTC-30000-241123",
    //         "timestamp": 1699584998504530,
    //         "turnover": 184.41206804,
    //         "turnover_symbol": "USDT",
    //         "turnover_usd": 184.41206804,
    //         "volume": 0.005
    //     }
    //
    ccxt::any timestamp =
        this->safeIntegerProduct(greeks, std::string("timestamp"), 0.001);
    ccxt::any marketId = this->safeString(greeks, std::string("symbol"));
    ccxt::any symbol = this->safeSymbol(marketId, market);
    ccxt::any stats =
        this->safeDict(greeks, std::string("greeks"), ccxt::dict{});
    ccxt::any quotes =
        this->safeDict(greeks, std::string("quotes"), ccxt::dict{});
    return ccxt::dict{
        {std::string("symbol"), symbol},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("delta"), this->safeNumber(stats, std::string("delta"))},
        {std::string("gamma"), this->safeNumber(stats, std::string("gamma"))},
        {std::string("theta"), this->safeNumber(stats, std::string("theta"))},
        {std::string("vega"), this->safeNumber(stats, std::string("vega"))},
        {std::string("rho"), this->safeNumber(stats, std::string("rho"))},
        {std::string("bidSize"),
         this->safeNumber(quotes, std::string("bid_size"))},
        {std::string("askSize"),
         this->safeNumber(quotes, std::string("ask_size"))},
        {std::string("bidImpliedVolatility"),
         this->safeNumber(quotes, std::string("bid_iv"))},
        {std::string("askImpliedVolatility"),
         this->safeNumber(quotes, std::string("ask_iv"))},
        {std::string("markImpliedVolatility"),
         this->safeNumber(quotes, std::string("mark_iv"))},
        {std::string("bidPrice"),
         this->safeNumber(quotes, std::string("best_bid"))},
        {std::string("askPrice"),
         this->safeNumber(quotes, std::string("best_ask"))},
        {std::string("markPrice"),
         this->safeNumber(greeks, std::string("mark_price"))},
        {std::string("lastPrice"),
         this->safeNumber(greeks, std::string("last_price"))},
        {std::string("underlyingPrice"),
         this->safeNumber(greeks, std::string("spot_price"))},
        {std::string("info"), greeks},
    };
  }

  /**
   * @method
   * @name delta#closeAllPositions
   * @description closes all open positions for a market type
   * @see https://docs.delta.exchange/#close-all-positions
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.user_id] the users id
   * @returns {object[]} A list of [position structures]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  closeAllPositions(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        awaitValue(this->loadMarkets());
                        ccxt::any request = ccxt::dict{
                            {std::string("close_all_portfolio"), true},
                            {std::string("close_all_isolated"), true},
                        };
                        ccxt::any response =
                            awaitValue(this->privatePostPositionsCloseAll(
                                this->extend(request, params)));
                        //
                        // {"result":{},"success":true}
                        //
                        ccxt::any position = this->parsePosition(this->safeDict(
                            response, std::string("result"), ccxt::dict{}));
                        return ccxt::list{position};
                      })
        .share();
  }

